⫻Kick La Metta | AI/TS:user
import { Template } from 'llamaindex';
import {
  init,
  loadAgent,
  plan,
  refine,
  refinePlan,
  roleplay,
  task,
} from 'kicklang';

// Initialize the LLM (AI) system, setting the context.
init({
  // Set the default role "Denis" for the user.
  user: {
    // Set the default role name for the user.
    name: 'Denis',
  },
  // Set the roles.
  roles: {
    // Set the role "Flow Master" for the user.
    'Flow Master': {
      // Set the role name.
      name: 'Flow Master',
      // Set the role description.
      description:
        'This role is a developer creating a flow chart using Neo4j\'s Cypher language for graph databases.',
      // Set the role instructions:
      instructions:
        'Use Cypher to express your work in a format suitable for a flow chart. This will enable easy visualization and understanding of the process.',
    },
    // Set the role "User" for the user.
    User: {
      // Set the role name.
      name: 'User',
      // Set the role description.
      description:
        'This role is a user testing a game. The user can provide feedback, refine the plan, and collaborate with the AI to create a powerful prompt for the game.',
      // Set the role instructions:
      instructions:
        'Provide feedback, refine the plan, and collaborate with the AI to create a powerful prompt for the game.',
    },
    // Set the role "Assistant" for the AI.
    Assistant: {
      // Set the role name.
      name: 'Assistant',
      // Set the role description.
      description:
        'This role is an assistant providing feedback to the user, refining the plan, and collaborating to create a powerful prompt for the game.',
      // Set the role instructions:
      instructions:
        'Provide feedback, refine the plan, and collaborate with the user to create a powerful prompt for the game.',
    },
  },
});

// Load the roles and templates.
const { Assistant, User, 'Flow Master': FlowMaster } = await loadAgent('role');

// Initialize the plan.
const plan = await plan(
  // The plan is a user task.
  task('Use the LLM to refine the plan.'),
  // Set the goal of the plan.
  'refine the plan',
  // Set the criteria of the plan.
  'correctness',
  // Set the "refine" action.
  refine,
  // Set the "refinePlan" action.
  refinePlan,
);

// Role-play the plan.
await roleplay(
  // The user role "User" is refining the plan.
  User.refine(plan),
  // The AI role "Assistant" is refining the plan.
  Assistant.refine(plan),
);

// Role-play a task as FlowMaster.
const query = await roleplay(
  // The user role "Flow Master" is querying "capital France".
  FlowMaster.task('(query (capital France))'),
);

// Role-play the task.
const refinedQuery = await roleplay(
  // The user role "User" is refining the query.
  User.refine(query),
  // The AI role "Assistant" is refining the query.
  Assistant.refine(query),
);

// Validate the refined query.
const correct = plan.validate(refinedQuery);
if (!correct) {
  // If the query is not correct, throw an error.
  throw new Error('The refined query is not correct.');
}

// Log the refined query.
console.log(JSON.stringify(refinedQuery, null, 2));

